def candy(ratings):
    n = len(ratings)
    c = [1] * n
    for i in range(1, n):                                  # left-to-right: left-neighbor constraint
        if ratings[i] > ratings[i - 1]:
            c[i] = c[i - 1] + 1
    for i in range(n - 2, -1, -1):                            # right-to-left: right-neighbor constraint
        if ratings[i] > ratings[i + 1]:
            c[i] = max(c[i], c[i + 1] + 1)
    return sum(c)

