public class Main {
    static int candy(int[] ratings) {
        int n = ratings.length;
        int[] c = new int[n];
        java.util.Arrays.fill(c, 1);
        for (int i = 1; i < n; i++) {                            // left-to-right: left-neighbor constraint
            if (ratings[i] > ratings[i - 1]) c[i] = c[i - 1] + 1;
        }
        for (int i = n - 2; i >= 0; i--) {                          // right-to-left: right-neighbor constraint
            if (ratings[i] > ratings[i + 1]) c[i] = Math.max(c[i], c[i + 1] + 1);
        }
        int total = 0;
        for (int x : c) total += x;
        return total;
    }
}

