        if (ratings[i] > ratings[i - 1]) c[i] = c[i - 1] + 1;
    }
    for (int i = n - 2; i >= 0; i--) {                              // right-to-left: right-neighbor constraint
        if (ratings[i] > ratings[i + 1]) c[i] = max(c[i], c[i + 1] + 1);
    }
    int total = 0;
    for (int x : c) total += x;
    return total;
}
